-- 1.17.23 一次性数据迁移：仍在使用旧版系统默认工作台「日常总览」的账号 → 跟随新的系统默认（「新手」预设）。
--
-- 范围：只动 workbench_configurations（账号级分析工作台配置），不碰账目、账本、分类、成员或其它表。
-- 识别：configuration.workspace 与旧版默认文档**完全相等**（jsonb 相等：键顺序无关，数组顺序、对象 ID
--   default-*、每张卡片的分析 / 展示形式 / 标题种类 / 排布全部一致）。这样的工作台只可能来自旧版
--   「恢复默认工作台」再点「完成」；任何一处不同都视为用户自己的布局，不在本迁移范围内。
-- 结果：workspace 置为 null（= 没有自定义，客户端显示当前系统默认，即新手布局；卡片标题随界面语言）。
--   「我的预设」列表原样保留；旧配置整份存入 previous_configuration 以便人工恢复；version + 1 让各设备的
--   同步按版本拿到新配置（本机保存的是同一份旧默认时直接安装，不产生冲突）。
-- 幂等：迁移由 _prisma_migrations 记录只执行一次；即使重放，已置 null 的行不再匹配，结果不变。
-- 与 packages/shared/src/workbench/legacyDefault.ts 的 LEGACY_DEFAULT_WORKSPACE 为同一份文档（测试比对）。
UPDATE "workbench_configurations"
SET
  "previous_configuration" = "configuration",
  "configuration" = jsonb_set("configuration", '{workspace}', 'null'::jsonb, false),
  "version" = "version" + 1,
  "updated_at" = CURRENT_TIMESTAMP
WHERE "schema_version" = 1
  AND "configuration" -> 'workspace' = '{"content":{"cards":[{"analysis":{"analysisId":"AN-B01","params":{}},"chart":{"chartFamily":"number"},"objectId":"default-b01","rangePolicy":"inherit","title":{"kind":"preset"},"type":"analysis-card"},{"analysis":{"analysisId":"AN-B02","params":{}},"chart":{"chartFamily":"number"},"objectId":"default-b02","rangePolicy":"inherit","title":{"kind":"preset"},"type":"analysis-card"},{"analysis":{"analysisId":"AN-B03","params":{}},"chart":{"chartFamily":"number"},"objectId":"default-b03","rangePolicy":"inherit","title":{"kind":"preset"},"type":"analysis-card"},{"analysis":{"analysisId":"AN-B06","params":{}},"chart":{"chartFamily":"number"},"objectId":"default-b06","rangePolicy":"inherit","title":{"kind":"preset"},"type":"analysis-card"},{"analysis":{"analysisId":"AN-I11","params":{}},"chart":{"chartFamily":"flow-bars"},"objectId":"default-i11","rangePolicy":"inherit","title":{"kind":"preset"},"type":"analysis-card"},{"analysis":{"analysisId":"AN-I01","params":{}},"chart":{"chartFamily":"donut"},"objectId":"default-i01","rangePolicy":"inherit","title":{"kind":"preset"},"type":"analysis-card"},{"analysis":{"analysisId":"AN-B09","params":{}},"chart":{"chartFamily":"extreme"},"objectId":"default-b09","rangePolicy":"inherit","title":{"kind":"preset"},"type":"analysis-card"},{"analysis":{"analysisId":"AN-B11","params":{}},"chart":{"chartFamily":"extreme"},"objectId":"default-b11","rangePolicy":"inherit","title":{"kind":"preset"},"type":"analysis-card"},{"analysis":{"analysisId":"AN-B15","params":{}},"chart":{"chartFamily":"extreme"},"objectId":"default-b15","rangePolicy":"inherit","title":{"kind":"preset"},"type":"analysis-card"},{"analysis":{"analysisId":"AN-A01","params":{}},"chart":{"chartFamily":"comparison"},"objectId":"default-a01","rangePolicy":"inherit","title":{"kind":"preset"},"type":"analysis-card"},{"analysis":{"analysisId":"AN-I12","params":{}},"chart":{"chartFamily":"heatmap"},"objectId":"default-i12","rangePolicy":"inherit","title":{"kind":"preset"},"type":"analysis-card"}],"containers":[{"children":["default-b09","default-b11","default-b15"],"objectId":"default-extremes","type":"carousel"}],"schemaVersion":1},"layout":{"layoutAlgorithmVersion":1,"main":{"baseCols":2,"objects":[{"anchor":1,"colSpan":1,"objectId":"default-b01","objectType":"analysis-card","rowSpan":1},{"anchor":2,"colSpan":1,"objectId":"default-b02","objectType":"analysis-card","rowSpan":1},{"anchor":3,"colSpan":1,"objectId":"default-b03","objectType":"analysis-card","rowSpan":1},{"anchor":4,"colSpan":1,"objectId":"default-b06","objectType":"analysis-card","rowSpan":1},{"anchor":5,"colSpan":2,"objectId":"default-i11","objectType":"analysis-card","rowSpan":2},{"anchor":9,"colSpan":2,"objectId":"default-i01","objectType":"analysis-card","rowSpan":3},{"anchor":15,"colSpan":2,"objectId":"default-extremes","objectType":"carousel","rowSpan":1},{"anchor":17,"colSpan":2,"objectId":"default-a01","objectType":"analysis-card","rowSpan":2},{"anchor":21,"colSpan":2,"objectId":"default-i12","objectType":"analysis-card","rowSpan":3}]},"mode":"unified","schemaVersion":1}}'::jsonb;
